/**
 * issue #66: closes the last generic loss window for autonomous Node-RED
 * source ingress (scheduled Inject, MQTT receive, Dashboard actions, etc.)
 * between Capture observing an emission and Temporal durably accepting the
 * corresponding `executeFlow` Workflow start.
 *
 * KISS design (see the issue): a file-per-event durable spool under the
 * runner's persistent userDir - no SQLite, no queue service, no new
 * daemon.
 *
 *   <dir>/<uuid>.json   - one durable record per pending ingress event
 *
 * Write path: temp file in the same directory -> fsync -> close -> atomic
 * rename to the final `<uuid>.json` name, so a crash mid-write can never
 * leave a corrupt "final" record (only a `.tmp` file, which is simply
 * ignored on scan).
 *
 * This module is intentionally split into small, independently testable
 * pieces:
 *   - pure primitives (write/list/remove one record on disk - M1)
 *   - `startIngressWorkflow` (the stable, retry-safe Workflow start helper -
 *     M2, mirrors `httpIngress.js`'s `deriveWorkflowId`/`startFlowWorkflow`
 *     pattern: `workflowIdReusePolicy: REJECT_DUPLICATE` +
 *     `WorkflowExecutionAlreadyStartedError` treated as success)
 *   - `createIngressSpool` (the stateful helper `worker.js` wires into
 *     Capture's `onIngress` and into startup recovery - M3/M4/M5)
 *
 * Persisted records intentionally carry the EXACT `executeFlow` start
 * input captured at ingress time (graph/nodeMeta/flowVersion/initial/
 * activityTaskQueue/nodeExecutionTimeoutMs) - a replayed record is never
 * rebuilt from the CURRENT flow, so a runner that restarts after a
 * redeploy cannot silently execute an old event against a new flow (the
 * existing `FLOW_VERSION_MISMATCH` contract remains the safe failure for
 * that case).
 */

"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

// M2/AC: modest, bounded, in-process retry backoff for a just-captured
// ingress record while the runner stays alive. No busy loop, no unbounded
// in-memory queue - once these are exhausted, the disk record is the sole
// source of truth and is picked up again by `replayPending()` on the next
// runner startup (or by a caller manually re-invoking replay).
const DEFAULT_RETRY_DELAYS_MS = [1000, 5000, 15000];

/**
 * @param {string} dir
 * @param {string} id
 * @returns {string}
 */
function finalPath(dir, id) {
    return path.join(dir, `${id}.json`);
}

/**
 * @param {string} dir
 * @param {string} id
 * @returns {string}
 */
function tempPath(dir, id) {
    return path.join(dir, `${id}.tmp`);
}

/**
 * M1: durably writes one ingress record - temp file, complete JSON write,
 * fsync, close, then an atomic rename to the final `<id>.json` name.
 * `record.id` must already be set (see `createIngressSpool().generateId`).
 *
 * @param {string} dir
 * @param {{id:string}} record
 * @returns {string} the final on-disk path
 */
function writeIngressRecord(dir, record) {
    fs.mkdirSync(dir, { recursive: true });
    const tmp = tempPath(dir, record.id);
    const final = finalPath(dir, record.id);
    const fd = fs.openSync(tmp, "w");
    try {
        fs.writeSync(fd, JSON.stringify(record));
        fs.fsyncSync(fd);
    } finally {
        fs.closeSync(fd);
    }
    fs.renameSync(tmp, final);
    return final;
}

/**
 * M1/M4: scans `dir` for pending, complete records (`*.json`, `*.tmp`
 * files are ignored - they are incomplete-write artifacts, never a final
 * record). A malformed final record (invalid JSON, or missing `id`) is
 * logged clearly and quarantined (renamed to `<name>.malformed`) rather
 * than crashing the whole scan/runner; if it cannot even be renamed, it is
 * simply skipped. Deterministic filename order is used - good enough per
 * the issue's own "keep ordering simple" guidance.
 *
 * @param {string} dir
 * @returns {Array<{id:string, record:object, path:string}>}
 */
function listPendingIngressRecords(dir) {
    if (!fs.existsSync(dir)) {
        return [];
    }
    const names = fs.readdirSync(dir).filter((name) => name.endsWith(".json")).sort();
    const pending = [];
    for (const name of names) {
        const full = path.join(dir, name);
        let parsed;
        try {
            parsed = JSON.parse(fs.readFileSync(full, "utf8"));
        } catch (err) {
            quarantine(full, `invalid JSON (${err && err.message ? err.message : err})`);
            continue;
        }
        if (!parsed || typeof parsed.id !== "string" || !parsed.id) {
            quarantine(full, "missing/invalid \"id\" field");
            continue;
        }
        pending.push({ id: parsed.id, record: parsed, path: full });
    }
    return pending;
}

/**
 * @param {string} full
 * @param {string} reason
 */
function quarantine(full, reason) {
    const quarantined = `${full}.malformed`;
    try {
        fs.renameSync(full, quarantined);
    } catch (err) {
        // Cannot even quarantine it (e.g. permissions) - leave it in place
        // rather than crashing the scan; it will simply be re-attempted
        // (and re-logged) on the next scan.
    }
    console.error(`[node-red-temporal] ingress spool: quarantined malformed record ${full} - ${reason}`);
}

/**
 * M1: idempotent delete - a second call for an already-removed id is a
 * harmless no-op (required for the "duplicate/already-started means
 * success, then delete" crash-window contract).
 *
 * @param {string} dir
 * @param {string} id
 */
function removeIngressRecord(dir, id) {
    try {
        fs.unlinkSync(finalPath(dir, id));
    } catch (err) {
        if (err.code !== "ENOENT") {
            throw err;
        }
    }
}

/**
 * @param {string} id
 * @returns {string}
 */
function deriveIngressWorkflowId(id) {
    return `ingress:${id}`;
}

/**
 * M2: the stable, retry-safe Workflow start helper. Same Workflow ID
 * (`ingress:<record.id>`) on every call for a given record, so a crash
 * between Temporal accepting the start and this process unlinking the
 * spool record is safe: the retry hits `WorkflowExecutionAlreadyStartedError`,
 * which is treated as success (`duplicate: true`), never a second Workflow.
 * Any other start error is rethrown so the record is left pending.
 *
 * @param {function(): Promise<object>} getClient
 * @param {{workflowTaskQueue:string, activityTaskQueue:string}} temporalConfig
 * @param {object} record - exact captured `executeFlow` start input, plus `id`
 * @returns {Promise<{workflowId:string, duplicate:boolean}>}
 */
async function startIngressWorkflow(getClient, temporalConfig, record) {
    // Defensive: some test doubles for `@temporalio/client` (this repo's
    // own convention, e.g. worker_spec.js's plain `stubClientModule`) only
    // stub `Connection`/`Client` and omit `WorkflowIdReusePolicy`/
    // `WorkflowExecutionAlreadyStartedError` entirely - fall back to
    // `undefined` (a harmless no-op `workflowIdReusePolicy` field) rather
    // than throwing on a destructure/property-access of an absent export.
    const clientModule = require("@temporalio/client");
    const WorkflowIdReusePolicy = clientModule.WorkflowIdReusePolicy;
    const WorkflowExecutionAlreadyStartedError = clientModule.WorkflowExecutionAlreadyStartedError;
    const workflowId = deriveIngressWorkflowId(record.id);
    const client = await getClient();
    try {
        await client.workflow.start("executeFlow", {
            taskQueue: temporalConfig.workflowTaskQueue,
            workflowId,
            workflowIdReusePolicy: WorkflowIdReusePolicy ? WorkflowIdReusePolicy.REJECT_DUPLICATE : undefined,
            args: [{
                graph: record.graph,
                nodeMeta: record.nodeMeta,
                flowVersion: record.flowVersion,
                initial: record.initial,
                activityTaskQueue: record.activityTaskQueue,
                nodeExecutionTimeoutMs: record.nodeExecutionTimeoutMs
            }]
        });
        return { workflowId, duplicate: false };
    } catch (err) {
        // Defensive: some test doubles for `@temporalio/client` (this
        // repo's own convention) only stub `Connection`/`Client` and omit
        // `WorkflowExecutionAlreadyStartedError` entirely - guard the
        // `instanceof` check so those still exercise the "other start
        // errors preserve the record" path instead of throwing a
        // `TypeError` from `instanceof` itself.
        if (typeof WorkflowExecutionAlreadyStartedError === "function" && err instanceof WorkflowExecutionAlreadyStartedError) {
            return { workflowId, duplicate: true };
        }
        throw err;
    }
}

/**
 * M3/M4/M5: the stateful spool `worker.js` wires into Capture's
 * `onIngress` (via `persistAndStart`) and into startup recovery (via
 * `replayPending`). Never lets a start failure become an unhandled
 * rejection or a busy loop - failures are logged and retried on a modest,
 * bounded backoff (`retryDelaysMs`), then left on disk for the next
 * `replayPending()` call (typically the next runner startup).
 *
 * @param {object} options
 * @param {string} options.dir - spool directory (created on first write)
 * @param {function(): Promise<object>} options.getClient
 * @param {{workflowTaskQueue:string, activityTaskQueue:string}} options.temporalConfig
 * @param {Array<number>} [options.retryDelaysMs]
 * @param {function(string): void} [options.log] - defaults to `console.error`
 * @returns {{dir:string, generateId:function():string, persistAndStart:function(object):Promise<void>, replayPending:function():Promise<void>, stop:function():void}}
 */
function createIngressSpool(options) {
    options = options || {};
    const dir = options.dir;
    const getClient = options.getClient;
    const temporalConfig = options.temporalConfig;
    const retryDelaysMs = options.retryDelaysMs || DEFAULT_RETRY_DELAYS_MS;
    const log = options.log || ((message) => console.error(message));
    const timers = new Set();

    function scheduleRetry(record, attempt) {
        if (attempt >= retryDelaysMs.length) {
            // Bounded backoff exhausted - the disk record remains the
            // source of truth and is retried by the next replayPending()
            // (typically the next runner startup), not by a busy loop here.
            return;
        }
        const timer = setTimeout(() => {
            timers.delete(timer);
            attemptStart(record, attempt + 1);
        }, retryDelaysMs[attempt]);
        // Never keep the process alive just for a pending retry timer.
        if (typeof timer.unref === "function") {
            timer.unref();
        }
        timers.add(timer);
    }

    /**
     * Attempts one Workflow start for `record`; on success (including
     * duplicate/already-started) removes the spool record. On failure,
     * logs and schedules a bounded retry. Never throws/rejects.
     *
     * @param {object} record
     * @param {number} attempt - 0 for the immediate, just-captured attempt
     * @returns {Promise<void>}
     */
    function attemptStart(record, attempt) {
        return startIngressWorkflow(getClient, temporalConfig, record).then(() => {
            removeIngressRecord(dir, record.id);
        }).catch((err) => {
            log(`[node-red-temporal] ingress spool: workflow start failed for ingress ${record.id} (attempt ${attempt + 1}): ${err && err.message ? err.message : err}`);
            scheduleRetry(record, attempt);
        });
    }

    return {
        dir,
        /**
         * @returns {string} a fresh, stable ingress record id (also used
         *   to derive the Workflow ID - `ingress:<id>`)
         */
        generateId() {
            return crypto.randomUUID();
        },
        /**
         * M3: durably persists `record` (must already have `.id` set),
         * then attempts the Workflow start immediately. Resolves once the
         * immediate attempt settles (success or first failure+scheduled
         * retry) - it never rejects.
         *
         * @param {object} record
         * @returns {Promise<void>}
         */
        persistAndStart(record) {
            writeIngressRecord(dir, record);
            return attemptStart(record, 0);
        },
        /**
         * M4: replays every currently pending record (startup recovery,
         * or an explicit manual re-drive). Never blocks forever on a
         * Temporal outage - each record gets its own bounded retry chain
         * exactly like `persistAndStart`, this call itself just resolves
         * once every record's IMMEDIATE attempt has settled.
         *
         * @returns {Promise<void>}
         */
        replayPending() {
            const pending = listPendingIngressRecords(dir);
            return Promise.all(pending.map((entry) => attemptStart(entry.record, 0))).then(() => undefined);
        },
        /**
         * M5: cancels any in-process retry timers (graceful shutdown).
         * Never deletes pending records - they remain for the next
         * `replayPending()`.
         */
        stop() {
            timers.forEach((timer) => clearTimeout(timer));
            timers.clear();
        }
    };
}

module.exports = {
    DEFAULT_RETRY_DELAYS_MS,
    writeIngressRecord,
    listPendingIngressRecords,
    removeIngressRecord,
    deriveIngressWorkflowId,
    startIngressWorkflow,
    createIngressSpool
};
